// valence MO filling for homonuclear diatomics of 2nd period: returns { bo, unp }
function moFill(ve, ntype) {
  const orbs = ntype ? [['s2s', 1, 1], ['s*2s', 1, -1], ['p2p', 2, 1], ['s2p', 1, 1], ['p*2p', 2, -1], ['s*2p', 1, -1]] : [['s2s', 1, 1], ['s*2s', 1, -1], ['s2p', 1, 1], ['p2p', 2, 1], ['p*2p', 2, -1], ['s*2p', 1, -1]];
  let left = ve, b = 0, a = 0, unp = 0;
  for (const [, deg, sign] of orbs) {
    const cap = 2 * deg; const take = Math.min(left, cap); left -= take;
    if (sign > 0) b += take; else a += take;
    // Hund: electrons spread singly first across degenerate orbitals
    const pairs = Math.max(0, take - deg); unp += take - 2 * pairs;
  }
  return { bo: (b - a) / 2, unp };
}
